file.content:
/* Layout and components. Values come from tokens.css. */
*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
  text-size-adjust: 100%;
}

body {
  margin: 0;
  background: var(--color-white);
  color: var(--color-ink);
  font-family: var(--font-family);
  font-size: var(--font-body-size);
  font-weight: var(--font-body-weight);
  line-height: var(--font-body-line-height);
}

a {
  color: inherit;
}

:focus-visible {
  outline: 3px solid var(--color-navy-hover);
  outline-offset: 2px;
}

/* top bar */
.top-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-4);
  min-height: calc(var(--touch-target) + 2 * var(--space-2));
  padding: var(--space-2) var(--space-4);
  background: var(--top-bar-background);
  color: var(--top-bar-foreground);
}

.top-bar a {
  display: inline-flex;
  align-items: center;
  min-height: var(--touch-target);
  text-decoration: none;
}

.top-bar :focus-visible {
  outline-color: var(--color-white);
}

.app-name {
  flex: none;
  font-size: var(--font-title-size);
  font-weight: var(--font-title-weight);
  line-height: var(--font-title-line-height);
}

.current-person {
  min-width: 0;
  gap: var(--space-2);
  padding: 0 var(--space-2);
  border-radius: var(--rounded-md);
}

.current-person:hover {
  background: var(--color-navy-hover);
}

.current-person-name {
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  font-weight: var(--font-label-weight);
}

.switch-hint {
  flex: none;
  font-size: var(--font-meta-size);
  line-height: var(--font-meta-line-height);
  text-decoration: underline;
}

/* page */
.page {
  max-width: 720px;
  margin: 0 auto;
  padding: var(--space-5) var(--space-4) var(--space-6);
}

.announce:empty {
  display: none;
}

.announce {
  max-width: 720px;
  margin: 0 auto;
  padding: var(--space-4) var(--space-4) 0;
}

.notice {
  margin: 0;
  padding: var(--space-3) var(--space-4);
  background: var(--color-navy-tint);
  border-radius: var(--rounded-sm);
}

.title {
  margin: 0 0 var(--space-4);
  font-size: var(--font-title-size);
  font-weight: var(--font-title-weight);
  line-height: var(--font-title-line-height);
}

.label {
  display: block;
  margin-bottom: var(--space-2);
  font-size: var(--font-label-size);
  font-weight: var(--font-label-weight);
  line-height: var(--font-label-line-height);
}

.meta,
.hint {
  color: var(--color-ink-muted);
  font-size: var(--font-meta-size);
  line-height: var(--font-meta-line-height);
}

.meta {
  margin: calc(-1 * var(--space-3)) 0 var(--space-4);
}

.hint {
  margin: var(--space-4) 0;
}

.lead {
  margin: 0;
}

/* controls */
.input {
  width: 100%;
  min-width: 0;
  min-height: var(--touch-target);
  padding: var(--space-2) var(--space-3);
  border: 1px solid var(--color-border);
  border-radius: var(--rounded-md);
  background: var(--color-white);
  color: var(--color-ink);
  font: inherit;
  font-size: var(--font-body-size);
}

.input:focus-visible {
  border-color: var(--color-navy);
}

.button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0 var(--space-4);
  font: inherit;
  font-size: var(--font-label-size);
  font-weight: var(--font-label-weight);
  cursor: pointer;
}

.button-primary {
  min-height: var(--button-primary-min-height);
  border: 1px solid var(--button-primary-background);
  border-radius: var(--button-primary-radius);
  background: var(--button-primary-background);
  color: var(--button-primary-foreground);
}

.button-primary:hover {
  background: var(--button-primary-hover);
}

.button-secondary {
  min-height: var(--button-secondary-min-height);
  border: 1px solid var(--button-secondary-border);
  border-radius: var(--button-secondary-radius);
  background: var(--button-secondary-background);
  color: var(--button-secondary-foreground);
}

/* pick your name */
.search-row {
  display: flex;
  gap: var(--space-2);
}

.people-list {
  margin: var(--space-4) 0 0;
  padding: 0;
  list-style: none;
}

.people-list li + li {
  margin-top: var(--space-2);
}

.people-list form {
  margin: 0;
}

.person-button {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  justify-content: space-between;
  gap: 0 var(--space-3);
  width: 100%;
  min-height: var(--touch-target);
  padding: var(--space-2) var(--space-4);
  border: 1px solid var(--color-border);
  border-radius: var(--rounded-md);
  background: var(--color-white);
  color: var(--color-ink);
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.person-button:hover {
  border-color: var(--color-navy);
  background: var(--color-navy-tint);
}

.person-name {
  font-weight: var(--font-label-weight);
}

.person-office {
  color: var(--color-ink-muted);
  font-size: var(--font-meta-size);
  line-height: var(--font-meta-line-height);
}

a.button {
  text-decoration: none;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}

.error-message {
  margin: 0;
  padding: var(--space-3) var(--space-4);
  background: var(--error-message-background);
  color: var(--error-message-foreground);
  border-radius: var(--error-message-radius);
}

.error-message p {
  margin: 0;
}

/* tabs (in the top bar) */
.top-bar {
  flex-wrap: wrap;
}

.tabs {
  display: flex;
  flex: 1 1 auto;
  gap: var(--space-2);
}

.tab {
  padding: 0 var(--space-3);
  border-radius: var(--rounded-md);
  font-size: var(--font-label-size);
  font-weight: var(--font-label-weight);
}

.tab:hover,
.tab[aria-current="page"] {
  background: var(--color-navy-hover);
}

.tab[aria-current="page"] {
  box-shadow: inset 0 -3px 0 var(--color-white);
}

@media (max-width: 767px) {
  .tabs {
    order: 3;
    flex-basis: 100%;
  }
}

/* manage rooms */
.subtitle {
  margin: var(--space-6) 0 var(--space-3);
  font-size: var(--font-body-size);
  font-weight: var(--font-label-weight);
  line-height: var(--font-body-line-height);
}

.rooms-table {
  width: 100%;
  border-collapse: separate;
  border-spacing: 0 var(--space-2);
}

.rooms-table th {
  padding: 0 var(--space-3);
  color: var(--color-ink-muted);
  font-size: var(--font-label-size);
  font-weight: var(--font-label-weight);
  line-height: var(--font-label-line-height);
  text-align: left;
}

.room-row td {
  height: var(--room-row-min-height);
  padding: var(--space-2) var(--space-3);
  border-top: 1px solid var(--room-row-border);
  border-bottom: 1px solid var(--room-row-border);
  background: var(--room-row-background);
  vertical-align: middle;
}

.room-row td:first-child {
  border-left: 1px solid var(--room-row-border);
  border-radius: var(--room-row-radius) 0 0 var(--room-row-radius);
}

.room-row td:last-child {
  border-right: 1px solid var(--room-row-border);
  border-radius: 0 var(--room-row-radius) var(--room-row-radius) 0;
}

.room-row td:only-child {
  border-radius: var(--room-row-radius);
}

/* A closed room is out of use, not an error: grey, never red. */
.room-row.is-closed td {
  background: var(--slot-closed-background);
  color: var(--slot-closed-foreground);
}

.room-name {
  font-weight: var(--font-label-weight);
}

.room-actions {
  text-align: right;
  white-space: nowrap;
}

.room-actions > * {
  vertical-align: middle;
}

.room-actions > * + * {
  margin-left: var(--space-2);
}

.room-actions form {
  display: inline;
  margin: 0;
}

.room-form,
.confirm {
  margin: 0;
}

.room-form .fields {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-3);
}

.field-name {
  flex: 1 1 16rem;
  min-width: 0;
}

.field-capacity {
  flex: 0 1 8rem;
  min-width: 0;
}

.room-form .error-message {
  margin-top: var(--space-3);
}

.form-actions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
  margin-top: var(--space-3);
}

.confirm-question {
  margin: 0;
}

/* Phone: the table becomes a simple list of room cards. */
@media (max-width: 767px) {
  .rooms-table thead {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip-path: inset(50%);
  }

  .rooms-table,
  .rooms-table tbody {
    display: block;
  }

  .room-row {
    display: flex;
    flex-wrap: wrap;
    align-items: baseline;
    gap: var(--space-1) var(--space-3);
    margin-bottom: var(--space-2);
    padding: var(--space-3) var(--space-4);
    border: 1px solid var(--room-row-border);
    border-radius: var(--room-row-radius);
    background: var(--room-row-background);
  }

  .room-row.is-closed {
    background: var(--slot-closed-background);
    color: var(--slot-closed-foreground);
  }

  .room-row td,
  .room-row td:first-child,
  .room-row td:last-child {
    display: block;
    height: auto;
    padding: 0;
    border: 0;
    border-radius: 0;
    background: transparent;
  }

  .room-row.is-closed td {
    background: transparent;
  }

  .room-name {
    flex: 1 1 0;
    order: 1;
    min-width: 0;
  }

  .room-status {
    order: 2;
  }

  .room-capacity {
    flex-basis: 100%;
    order: 3;
    color: var(--color-ink-muted);
    font-size: var(--font-meta-size);
    line-height: var(--font-meta-line-height);
  }

  .room-capacity::before {
    content: attr(data-label) " ";
  }

  .room-row.is-closed .room-capacity {
    color: inherit;
  }

  .room-row td[colspan] {
    flex-basis: 100%;
  }

  .room-row td.room-actions {
    display: flex;
    flex-basis: 100%;
    order: 4;
    gap: var(--space-2);
    margin-top: var(--space-2);
    text-align: left;
  }

  .room-actions > * + * {
    margin-left: 0;
  }
}

/* rooms: find a free room */
.slot-form {
  margin: 0;
}

.slot-form .fields {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: var(--space-3);
}

@media (max-width: 767px) {
  .slot-form .fields {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

.rooms-results .error-message {
  margin-top: var(--space-5);
}

.office-name {
  margin: var(--space-4) 0 var(--space-2);
  font-size: var(--font-label-size);
  font-weight: var(--font-label-weight);
  line-height: var(--font-label-line-height);
}

.meta-inline {
  color: var(--color-ink-muted);
  font-weight: var(--font-meta-weight);
}

.free-rooms,
.booking-list,
.chosen-list,
.attendee-names {
  margin: 0;
  padding: 0;
  list-style: none;
}

.free-room,
.chosen {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--space-1) var(--space-3);
  min-height: var(--room-row-min-height);
  margin-bottom: var(--space-2);
  padding: var(--space-2) var(--space-3) var(--space-2) var(--space-4);
  border: 1px solid var(--room-row-border);
  border-radius: var(--room-row-radius);
  background: var(--room-row-background);
}

.free-room .room-name,
.chosen .person-name {
  flex: 1 1 0;
  min-width: 0;
}

.room-seats {
  color: var(--color-ink-muted);
  font-size: var(--font-meta-size);
  line-height: var(--font-meta-line-height);
}

.booking-item + .booking-item {
  margin-top: var(--space-2);
}

.booking-link {
  display: flex;
  flex-direction: column;
  padding: var(--space-2) var(--space-4);
  border-radius: var(--slot-booked-radius);
  background: var(--slot-booked-background);
  color: var(--slot-booked-foreground);
  text-decoration: none;
}

.booking-link:hover {
  box-shadow: inset 0 0 0 1px var(--color-navy);
}

.booking-title {
  font-weight: var(--font-label-weight);
}

.booking-when,
.booking-where {
  font-size: var(--font-meta-size);
  line-height: var(--font-meta-line-height);
}

/* booking form and details */
.booking-form .field,
.attendees {
  margin: 0 0 var(--space-4);
}

.attendees {
  padding: 0;
  border: 0;
}

/* the booking form's time pickers, shown only when the slot can't be booked */
.pick-time {
  margin: 0 0 var(--space-4);
  padding: 0;
  border: 0;
}

.pick-time .fields {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: var(--space-3);
}

.pick-time .field {
  margin: 0;
}

@media (max-width: 767px) {
  .pick-time .fields {
    grid-template-columns: minmax(0, 1fr);
  }
}

.attendees .hint {
  margin: 0 0 var(--space-3);
}

.booking-details {
  display: grid;
  grid-template-columns: max-content 1fr;
  gap: var(--space-2) var(--space-4);
  margin: 0 0 var(--space-4);
}

.booking-details dt {
  color: var(--color-ink-muted);
  font-size: var(--font-label-size);
  font-weight: var(--font-label-weight);
  line-height: var(--font-body-line-height);
}

.booking-details dd {
  margin: 0;
}

.back-link {
  margin-top: var(--space-5);
}

/* my bookings: day and week calendar */
.calendar-nav {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: var(--space-3);
  margin: 0 0 var(--space-4);
}

.calendar-views,
.calendar-steps {
  display: flex;
  gap: var(--space-2);
}

.calendar-views [aria-current="page"] {
  background: var(--color-navy);
  color: var(--color-white);
}

.calendar-heading.is-today,
.calendar-day.is-today .calendar-day-heading {
  background: var(--color-navy-tint);
}

.calendar-heading.is-today {
  padding: var(--space-1) var(--space-2);
  border-radius: var(--rounded-sm);
}

.calendar-bookings {
  margin: 0;
  padding: 0;
  list-style: none;
}

.calendar-booking + .calendar-booking {
  margin-top: var(--space-2);
}

.calendar-booking-link {
  display: flex;
  flex-direction: column;
  min-height: var(--touch-target);
  padding: var(--space-2) var(--space-3);
  border-radius: var(--slot-mine-radius);
  background: var(--slot-mine-background);
  color: var(--slot-mine-foreground);
  text-decoration: none;
}

.calendar-booking-link:hover {
  background: var(--color-navy-hover);
}

.calendar-booking-link:focus-visible {
  outline: 3px solid var(--color-navy);
  outline-offset: 2px;
}

.booking-role {
  font-size: var(--font-meta-size);
  line-height: var(--font-meta-line-height);
}

.calendar-day-heading {
  margin: 0 0 var(--space-2);
  padding: var(--space-1) var(--space-2);
  border-radius: var(--rounded-sm);
  font-size: var(--font-label-size);
  font-weight: var(--font-label-weight);
  line-height: var(--font-label-line-height);
}

.calendar-nothing {
  margin: 0;
  padding: 0 var(--space-2);
  color: var(--color-ink-muted);
  font-size: var(--font-meta-size);
}

.calendar-week .calendar-day + .calendar-day {
  margin-top: var(--space-4);
}

@media (min-width: 768px) {
  .calendar-week {
    display: grid;
    grid-template-columns: repeat(7, minmax(0, 1fr));
    border: 1px solid var(--color-border);
    border-radius: var(--rounded-sm);
  }

  .calendar-week .calendar-day {
    min-height: 240px;
    padding: var(--space-2);
    overflow-wrap: anywhere;
  }

  .calendar-week .calendar-day + .calendar-day {
    margin-top: 0;
    border-left: 1px solid var(--color-border);
  }

  .calendar-week .calendar-day.is-today {
    background: var(--color-navy-tint);
  }
}

@media (max-width: 767px) {
  .step-label {
    display: none;
  }
}

/* the week needs room for seven columns */
.page:has(.calendar-week) {
  max-width: 1120px;
}

